import{z as o,x as s,o as n,c as p,q as t,j as i,D as e,d as A,s as l,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"盈利质量","description":"","frontmatter":{"title":"盈利质量","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/earnings-quality.md","filePath":"quant/earnings-quality.md","lastUpdated":1791063341000}'),d={name:"quant/earnings-quality.md"};function D(h,a,u,c,m,C){const B=s("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="盈利质量" tabindex="-1">盈利质量 <a class="header-anchor" href="#盈利质量" aria-label="Permalink to &quot;盈利质量&quot;">​</a></h1><div class="epigraph"><p>利润的数字可以相同，持续进入现金的能力可以差很远；质量问的是盈余里有多少会在后续期间反转。</p><footer>—— 据 Dechow and Dichev, The Accounting Review, 2002；Penman and Zhang, The Accounting Review, 2002 整理</footer></div><p>上一课<a href="/quant/survivorship-delist">幸存者与退市</a>把失败公司留在宇宙里。现在可以问利润本身好不好。上一课<a href="/quant/accrual-vs-cash">应计与现金流</a>已经拆开应计分量；本课把「质量」从单一应计排序扩成：哪些盈余更可持续、哪些更像一次性或估计噪声。不重做 PIT，也不把商誉减值提前讲完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>低应计只是质量的一个代理。同一应计水平下，营运资本应计与长期应计的反转速度不同；同一净利润下，经常性经营利润与处置收益的持续性不同。Dechow–Dichev 把应计质量写成营运资本应计对过去、当期、未来现金流的拟合残差：残差大，应计更像估计误差。Penman–Zhang 从稳健会计出发，指出隐藏储备会压低当期利润、抬高后续利润，使「高质量」与「保守」缠在一起。</p><p><span class="marginnote">直觉类比：两个人月入都是 2 万，一个靠工资、月月都有，另一个靠偶尔卖旧货。质量问的就是「下个月还在不在」。报表同理：同样的净利润，现金撑着的经常性利润可持续，处置资产的一次性收益下季就没了。</span></p><p>缺口是：在已有应计定义上，给后课一个<strong>可排序的质量对象</strong>，而不是审计意见百科。</p><h3 id="质量不是扣非后利润的别名" tabindex="-1">质量不是扣非后利润的别名 <a class="header-anchor" href="#质量不是扣非后利润的别名" aria-label="Permalink to &quot;质量不是扣非后利润的别名&quot;">​</a></h3><p>扣除非经常项目得到的「经常性利润」仍可以全是应计。质量问的是确认过程与现金实现的匹配，不是科目是否带「营业外」标签。把质量做成扣非，后面的因子会忽略折旧政策、收入确认与坏账估计——这些才是应计里持续或反转的来源。</p><p><span class="marginnote">Jones 与修正 Jones 模型把应计拆成「正常」与「可操纵」；回测里它们噪声大、对成长公司偏差明显。本课把它们当对照，不当前提。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>后课可用的质量信号，优先用已有字段组合，而不是先估一个操纵模型。常用三层：（1）应计总量或营运资本应计，Sloan 口径；（2）应计与现金流的匹配残差，Dechow–Dichev 口径；（3）一次性项目、中断经营、会计变更的指示变量，用来降权而非单独开一个「质量因子」。缩放仍用期初资产或平均资产，与应计课一致。</p><p><span class="marginnote">「DD 残差」翻译一下：应计里模型解释不掉的部分。营运资本应计本应与前后期现金流大致对上账，对不上的差额被当成估计误差——残差越大，说明利润越像「估出来的」而不是「赚出来的」。</span></p><p>计算必须走 PIT 与当时宇宙：用重述后变「干净」的利润来定义历史质量，是前视；丢掉退市公司再比质量，是幸存者。质量因子的空头往往集中在即将变差的公司，样本规则比模型选择更致命。</p>',14)),(n(),i(r,null,{default:e(()=>[l(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20NI%5B%22%E5%87%80%E5%88%A9%E6%B6%A6%22%5D%20--%3E%20ACC%5B%22%E5%BA%94%E8%AE%A1%E5%88%86%E9%87%8F%22%5D%0A%20%20NI%20--%3E%20CASH%5B%22%E7%8E%B0%E9%87%91%E5%88%86%E9%87%8F%22%5D%0A%20%20ACC%20--%3E%20MATCH%5B%22%E4%B8%8E%E7%8E%B0%E9%87%91%E6%B5%81%E5%8C%B9%E9%85%8D%22%5D%0A%20%20MATCH%20--%3E%20Q%5B%22%E8%B4%A8%E9%87%8F%E6%8E%92%E5%BA%8F%22%5D%0A%20%20ONE%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E9%A1%B9%E7%9B%AE%22%5D%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"未来现金流项若直接取已实现 OCF，Dechow–Dichev 会前视。用公告前已有的过去与当期匹配，或用当时现金流预期替代「未来」。年报质量按可用日期更新，不按日历年冻整年。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"常见误区：把 DD 公式里的「未来现金流」直接取已实现的明年 OCF——公式照抄了，信息却用了还没发生的。回测因此虚高；实盘那一刻你并不知道明年现金流，必须用当时可得的过去与当期匹配来近似。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"投资者若对盈余总量反应，对低持续性分量反应不足，则低质量公司随后回报偏低。机制不必假设欺诈：估计误差、增长带来的营运资本、稳健会计的储备释放，都会改变后续实现。因子管道里，质量常与价值、盈利共线——便宜可能是因为利润不可持续。后课账面与无形资产会把「便宜」再拆一刀；本课先保证利润侧不是总量。",-1)),a[7]||(a[7]=E("p",null,"同样一亿元净利润，成分不同导致的持续性分化：",-1)),(n(),i(r,null,{default:e(()=>[l(B,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20NI%5B%22%E5%87%80%E5%88%A9%E6%B6%A6%EF%BC%9A%E5%90%8C%E4%B8%BA%201%20%E4%BA%BF%22%5D%20--%3E%20A%5B%22%E7%BB%8F%E5%B8%B8%E6%80%A7%E7%BB%8F%E8%90%A5%E5%88%A9%E6%B6%A6%EF%BC%9A%E7%8E%B0%E9%87%91%E6%94%AF%E6%92%91%22%5D%0A%20%20NI%20--%3E%20B%5B%22%E4%B8%80%E6%AC%A1%E6%80%A7%E6%94%B6%E7%9B%8A%EF%BC%9A%E5%A4%84%E7%BD%AE%E8%B5%84%E4%BA%A7%E6%88%96%E8%A1%A5%E5%8A%A9%22%5D%0A%20%20NI%20--%3E%20C%5B%22%E5%BA%94%E8%AE%A1%E5%A0%86%E7%A7%AF%EF%BC%9A%E5%BA%94%E6%94%B6%E4%B8%8E%E5%AD%98%E8%B4%A7%E7%8C%9B%E5%A2%9E%22%5D%0A%20%20A%20--%3E%20S%5B%22%E4%B8%8B%E5%AD%A3%E5%A4%A7%E6%A6%82%E7%8E%87%E9%87%8D%E7%8E%B0%EF%BC%9A%E6%8C%81%E7%BB%AD%E6%80%A7%E9%AB%98%22%5D%0A%20%20B%20--%3E%20R1%5B%22%E4%B8%8B%E5%AD%A3%E6%B6%88%E5%A4%B1%EF%BC%9A%E7%9B%B4%E6%8E%A5%E5%8F%8D%E8%BD%AC%22%5D%0A%20%20C%20--%3E%20R2%5B%22%E7%8E%B0%E9%87%91%E4%B8%8D%E5%85%91%E7%8E%B0%EF%BC%9A%E5%9D%8F%E8%B4%A6%E4%B8%8E%E5%87%8F%E5%80%BC%E5%9F%8B%E9%9B%B7%22%5D%0A%20%20R1%20--%3E%20LOW%5B%22%E4%BD%8E%E8%B4%A8%E9%87%8F%EF%BC%9A%E9%9A%8F%E5%90%8E%E5%9B%9E%E6%8A%A5%E5%81%8F%E4%BD%8E%22%5D%0A%20%20R2%20--%3E%20LOW%0A%20%20S%20--%3E%20HIGH%5B%22%E9%AB%98%E8%B4%A8%E9%87%8F%EF%BC%9A%E5%8F%AF%E6%8C%81%E7%BB%AD%E7%9B%88%E4%BD%99%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">质量信号换手往往高于价值：应计反转快。回测要按可用日期重算，不能把年报质量冻结到下一份年报之前的每一个交易日还当新信息。</span></p><p>把一次性项目做成 0/1 降权，比估一套可操纵应计更稳。Dechow–Dichev 残差需要未来现金流，直接用未来 OCF 会前视；实务上用已实现的过去与当期匹配，或把「未来」项改成当时分析师对现金流的预期。质量信号至少按季随可用日期更新，不要把年报质量冻到下一个年报之前的每一个再平衡日还当新信息。与价值共线时，先报告行业内相关，再决定是否正交。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写审计准则，不估计完整盈余管理模型。商誉减值、递延税、股份支付会扭曲利润，分别交给后面几课。分析师预期与惊喜是再后面的信息事件，不是质量定义。后课默认：讨论盈利先问持续性与现金匹配，再问多少。</p><p>后课默认：讨论盈利先问应计匹配与一次性降权，再问水平高低。Jones 类操纵模型只作对照，不作主干信号。质量与价值的相关在行业内报告；若你正交，要声明是对行业内残差正交还是对全样本账面市值正交，两者改的截面不同。</p><p>质量管道换手高于价值：应计反转快，必须按可用日期重算，不能把一份年报质量冻到下一份年报之前的每一个再平衡日。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应计是质量的入口，不是质量的全部。</li><li>Dechow–Dichev：应计与现金流匹配越差，质量越低。</li><li>扣非不等于质量；一次性项目只是降权标签。</li><li>质量排序必须在 PIT 与含退市的宇宙上做。</li><li>质量与价值共线，后面拆账面时还要用到。</li><li>出处：Dechow and Dichev (2002)；Penman and Zhang (2002)；Sloan (1996)。</li></ul>',8))])}const T=o(d,[["render",D]]);export{f as __pageData,T as default};
